export const AGENTE_PROTOCOL_VERSION = 2;

export interface ApprovalDecision {
  decision: ApprovalDecisionKind;
  request_id: string;
}

export type ApprovalDecisionKind = "approve_once" | "approve_all" | "deny" | "cancel";

export interface Attachment {
  bytes: number;
  kind: AttachmentKind;
  /** MIME type (`image/png`, `audio/mpeg`, `video/mp4`, `application/pdf`). */
  mime: string;
  /** Original file name, for display. */
  name: string;
  /** Absolute path of the stored copy. */
  path: string;
}

/** What kind of media an attachment is, which decides how each provider format carries it and which models accept it. */
export type AttachmentKind = "image" | "audio" | "video" | "pdf";

export interface ChildSnapshot {
  run_id: string;
  status: string;
  summary?: string | null;
}

export interface ClientToolCall {
  arguments: unknown;
  call_id: string;
  name: string;
  request_id: string;
  session_id: string;
  turn_id: string;
}

export interface ClientToolDefinition {
  description: string;
  mutating?: boolean;
  name: string;
  parameters: unknown;
  sequential?: boolean;
}

export interface ClientToolResult {
  attachments?: Attachment[];
  content: string;
  is_error?: boolean;
  request_id: string;
  session_id: string;
  turn_id: string;
}

export interface FunctionCall {
  arguments: string;
  name: string;
}

/** Home turns expose only client-owned tools, never the coding tool registry. */
export interface HomeTurnPolicy {
  max_iterations: number;
  max_time_ms: number;
  max_tool_calls: number;
}

export interface Message {
  /** Media sent with a user message (images, audio, video, PDFs). Each is a stored copy on disk; providers encode it at request time, so saved sessions carry references, not bytes. */
  attachments?: Attachment[];
  content: string;
  /** Ordered provider-native blocks needed for lossless tool/reasoning replay. */
  continuation?: ProviderContinuation | null;
  role: Role;
  thinking?: string | null;
  thinking_signature?: string | null;
  tool_call_id?: string | null;
  tool_calls?: ToolCall[] | null;
}

/** Where a turn came from: a client (tui, desktop, web) or a bot channel. */
export interface Origin {
  channel: string;
  sender?: string | null;
  trust?: Trust;
}

export interface ProviderContinuation {
  blocks: unknown[];
  model_id: string;
  provider_id: string;
}

export interface RegisterClientTools {
  session_id: string;
  tools: ClientToolDefinition[];
}

export type Role = "system" | "user" | "assistant" | "tool";

